{"content": "#!/usr/bin/env python3
"""Fill the <!-- TABLE:x --> markers of docs/BENCHMARKS.md from the campaign reports."""
from __future__ import annotations

import json
import pathlib
import sys

REPO = pathlib.Path("/work/e2repo")
REPORTS = pathlib.Path("/work/e2-scratch/reports")
sys.path.insert(0, str(REPO / "src"))

from ggufone.bench import harness  # noqa: E402


def load(name: str) -> dict | None:
    path = REPORTS / f"{name}.json"
    if not path.exists():
        return None
    return json.loads(path.read_text())


def number(value: object, digits: int = 3) -> str:
    if value is None:
        return "—"
    if isinstance(value, int):
        return f"{value:,}"
    if isinstance(value, float):
        return f"{value:,.{digits}f}" if abs(value) >= 1 else f"{value:.4f}"
    return str(value)


def rows(summary: dict | None, label: str) -> str:
    if not summary:
        return f"| {label} | — | — | — | — |"
    return (f"| {label} | {number(summary.get('n'))} | {number(summary.get('p50'))} | "
            f"{number(summary.get('p95'))} | {number(summary.get('min'))} | "
            f"{number(summary.get('max'))} |")


def latency_table(report: dict) -> str:
    lines = [harness.render_report(report).strip(), ""]
    return "\n".join(lines)


def host_table(latency: dict) -> str:
    host = latency["host"]
    model = latency["model"]
    return "\n".join([
        "| what | value |", "|---|---|",
        f"| platform | `{host['platform']}` |",
        f"| CPUs seen | {host['cpu_count']} |",
        f"| cgroup CPU quota | {host.get('cgroup_cpu_max')} CPU-seconds/s |",
        f"| cgroup memory limit | {number((host.get('cgroup_memory_bytes') or 0) / 2**30, 1)} GiB |",
        f"| runtime | pinned `llama-b11026-bin-ubuntu-x64` (CPU) |",
        f"| model | `{model['name']}` — {number(model.get('bytes'))} B, arch `{model.get('arch')}`, "
        f"{model.get('quant')} |",
    ])


def amortisation_table(spark: dict, qwen: dict | None) -> str:
    lines = ["| model | model_load_ms (p50) | serve ms/request (p50) | one-shot ms/request | saved |",
             "|---|---|---|---|---|"]
    for report, label in ((spark, "Spark-X2.5-4B"), (qwen, "Qwen3.5-0.8B")):
        if not report:
            continue
        row = report["load_amortisation"]
        lines.append(f"| {label} | {number(row['model_load_ms'])} | "
                     f"{number(row['serve_ms_per_request'])} | "
                     f"{number(row['one_shot_ms_per_request'])} | "
                     f"{number(row['saved_ms_per_request'])} |")
    return "\n".join(lines)


def wave_table(latency: dict) -> str:
    account = latency.get("wave_accounting", {})
    lines = ["| request | forks | waves | decode steps | ms (p50) |", "|---|---|---|---|---|"]
    for row in latency.get("per_question", []):
        lines.append(f"| choice, {row['candidates']} candidates | {row['forks']} | {row['waves']} | "
                     f"{row['decode_steps']} | {number(row['ms']['p50'])} |")
    lines.append(f"| the accounting request (5 candidates, n_seq_max=6) | 5 | "
                 f"{account.get('waves')} | — | — |")
    lines.append("")
    lines.append(f"`wave_accounting` of the published run: `groups={account.get('groups')}`, "
                 f"`suffix_decodes={account.get('suffix_decodes')}`, "
                 f"`step_decodes={account.get('step_decodes')}`, `waves={account.get('waves')}`.")
    return "\n".join(lines)


def quality_table(report: dict) -> str:
    return harness.render_report(report).strip()


def throughput_table(spark: dict, qwen: dict | None) -> str:
    lines = ["| model | backend | placement | prefill tok/s (p50) | decision ms (p50) | "
             "load ms (p50) | decision tok/s (p50) | unavailable |",
             "|---|---|---|---|---|---|---|---|"]
    for report, label in ((spark, "Spark-X2.5-4B"), (qwen, "Qwen3.5-0.8B")):
        if not report:
            continue
        for row in report["backends"]:
            if row.get("measured"):
                lines.append(f"| {label} | {row['backend']} | `{row['placement']}` | "
                             f"{number(row['prefill_tok_per_s']['p50'])} | "
                             f"{number(row['decision_ms']['p50'])} | "
                             f"{number(row['load_ms']['p50'])} | "
                             f"{number(row['decision_tok_per_s']['p50'])} | |")
            else:
                lines.append(f"| {label} | {row['backend']} | — | — | — | — | — | "
                             f"{row['reason']} |")
    return "\n".join(lines)


def determinism_table(spark: dict, qwen: dict | None) -> str:
    lines = ["| model | backend | threads | repeats | identical | digest |", "|---|---|---|---|---|---|"]
    for report, label in ((spark, "Spark-X2.5-4B"), (qwen, "Qwen3.5-0.8B")):
        if not report:
            continue
        for row in report["backends"]:
            digests = row.get("digests") or ["—"]
            lines.append(f"| {label} | {row['backend']} | {row.get('threads')} | "
                         f"{report['repeats']} | {'yes' if row['identical'] else 'NO'} | "
                         f"`{digests[0][:30]}…` |")
        for backend, reason in (report.get("skipped_backends") or {}).items():
            lines.append(f"| {label} | {backend} | — | — | not measured | {reason} |")
    return "\n".join(lines)


def threads_table(reports: list[tuple[int, dict]]) -> str:
    lines = ["| threads | prefill 256 tok/s (p50) | prefill ms (p50) | decision ms (p50, 4 cand) | "
             "model load ms (p50) |", "|---|---|---|---|---|"]
    for threads, report in sorted(reports, key=lambda item: item[0]):
        prefill = report["prefill"][0]
        decision = next((row for row in report["per_question"] if row["candidates"] == 4),
                        report["per_question"][0])
        lines.append(f"| {threads} | {number(prefill['tok_per_s']['p50'])} | "
                     f"{number(prefill['ms']['p50'], 1)} | {number(decision['ms']['p50'], 1)} | "
                     f"{number(report['model_load']['p50'], 1)} |")
    return "\n".join(lines)


def apply(markdown: str, table: str, body: str) -> str:
    marker = f"<!-- TABLE:{table} -->"
    assert marker in markdown, f"marker {marker} is gone"
    return markdown.replace(marker, body)


def main() -> int:
    path = REPO / "docs" / "BENCHMARKS.md"
    markdown = path.read_text(encoding="utf-8")
    spark_latency = load("spark_latency")
    qwen_latency = load("qwen_latency")
    spark_quality = load("spark_quality")
    qwen_quality = load("qwen_quality")
    spark_thr = load("spark_throughput")
    qwen_thr = load("qwen_throughput")
    spark_det = load("spark_determinism")
    qwen_det = load("qwen_determinism")
    threads_reports = [(threads, load(f"spark_t{threads}_latency"))
                       for threads in (1, 2, 4, 8, 24)]
    threads_reports = [(threads, report) for threads, report in threads_reports if report]

    replacements: list[tuple[str, str]] = []
    if spark_latency:
        replacements.append(("host", host_table(spark_latency)))
