{"new_string": "def quality_split_table(spark: dict | None, qwen: dict | None) -> str:
    """Agreement split by the engine's own `reliability` flag — the R4 diagnostic at work."""
    lines = ["| model | reliability | items | correct | agreement | 95% CI | note |",
             "|---|---|---|---|---|---|---|"]
    for report, label in ((spark, "Spark-X2.5-4B"), (qwen, "Qwen3.5-0.8B")):
        if not report:
            continue
        for flag in ("ok", "low_mass"):
            rows = [row for row in report["items"] if row.get("reliability") == flag]
            if not rows:
                continue
            summary = suites_agreement(rows)
            note = ("candidate mass dominates the row" if flag == "ok"
                    else "most of the row's mass sits outside the candidate set — the "
                         "restricted softmax is reading a tail")
            lines.append(f"| {label} | `{flag}` | {summary['n']} | {summary['correct']} | "
                         f"{number(summary['agreement'])} | {number(summary['ci'][0])} – "
                         f"{number(summary['ci'][1])} | {note} |")
    return "\n".join(lines)


def suites_agreement(rows: list[dict]) -> dict:
    """The same exact-match + Wilson computation the suite uses (documents, no new numbers)."""
    correct = sum(1 for row in rows if row["correct"])
    low, high = harness.wilson_interval(correct, len(rows))
    return {"n": len(rows), "correct": correct,
            "agreement": (correct / len(rows)) if rows else 0.0, "ci": [low, high]}


