{"content": "import json
import pathlib

REPORTS = pathlib.Path("/work/e2-scratch/reports")
spark = json.loads((REPORTS / "spark_quality.json").read_text())
qwen = json.loads((REPORTS / "qwen_quality.json").read_text())
spark_items = {item["id"]: item for item in spark["items"]}
qwen_items = {item["id"]: item for item in qwen["items"]}

print("=== agreement by reliability flag ===")
for label, report in (("spark", spark), ("qwen", qwen)):
    for flag in sorted({item["reliability"] for item in report["items"]}):
        rows = [item for item in report["items"] if item["reliability"] == flag]
        correct = sum(1 for item in rows if item["correct"])
        print(f"{label:6s} {flag:10s} n={len(rows):3d} correct={correct:3d} "
              f"agreement={correct / len(rows):.3f}")

print("\n=== score items: which level was answered ===")
for label, items in (("spark", spark_items), ("qwen", qwen_items)):
    got = {}
    for item in items.values():
        if item["type"] == "score":
            got[item["got"]] = got.get(item["got"], 0) + 1
    print(f"{label:6s} answered levels: {dict(sorted(got.items()))}")

same = [item_id for item_id, item in spark_items.items()
        if item["type"] == "score" and not item["correct"] and not qwen_items[item_id]["correct"]]
spark_wrong = {i for i, item in spark_items.items() if item["type"] == "score" and not item["correct"]}
qwen_wrong = {i for i, item in qwen_items.items() if item["type"] == "score" and not item["correct"]}
print(f"score misses: spark={len(spark_wrong)} qwen={len(qwen_wrong)} "
      f"shared={len(spark_wrong & qwen_wrong)}")
print(f"overall: spark correct={sum(1 for i in spark_items.values() if i['correct'])} "
      f"qwen correct={sum(1 for i in qwen_items.values() if i['correct'])}")
shared_full = {i for i, item in spark_items.items() if item["correct"]} == \
    {i for i, item in qwen_items.items() if item["correct"]}
print(f"identical correct sets: {shared_full}")

print("\n=== choice misses with a confident wrong answer (spark) ===")
for item in spark["items"]:
    if item["type"] == "choice" and not item["correct"] and item["confidence"] > 0.5:
        print(f"{item['id']} gold={item['expected']} got={item['got']} "
              f"p={item['probabilities'][item['got']]:.3f} cov={item['coverage']:.3f} "
              f"rel={item['reliability']}")

print("\n=== per-item agreement by type, both models ===")
for qtype in ("choice", "score", "noul"):
    ids = [i for i, item in spark_items.items() if item["type"] == qtype]
    both = sum(1 for i in ids if spark_items[i]["correct"] and qwen_items[i]["correct"])
    spark_only = sum(1 for i in ids if spark_items[i]["correct"] and not qwen_items[i]["correct"])
    qwen_only = sum(1 for i in ids if not spark_items[i]["correct"] and qwen_items[i]["correct"])
    neither = sum(1 for i in ids if not spark_items[i]["correct"] and not qwen_items[i]["correct"])
    print(f"{qtype:7s} n={len(ids):3d} both={both:3d} spark_only={spark_only:3d} "
          f"qwen_only={qwen_only:3d} neither={neither:3d}")
